const motionButton=document.querySelector('#motion-toggle');function setPause(value){paused=value;motionButton.textContent=(paused?'Resume':'Pause')+' motion';motionButton.setAttribute('aria-pressed',paused);document.body.classList.toggle('motion-paused',paused);venueCarousel?.refresh()}motionButton.onclick=()=>setPause(!paused);reduced.addEventListener('change',e=>setPause(e.matches));
