 const hero=document.querySelector('.hero');
 venueCarousel=createVenueCarousel({slides:[...document.querySelectorAll('.hero-slide')],buttons:[...document.querySelectorAll('[data-sport]')],toggle:document.querySelector('#carousel-toggle'),onChange:sport=>{document.querySelector('#venue-label').textContent=sport==='football'?'STADIUM SOUND':sport==='mlb'?'BALLPARK SOUND':sport==='concert'?'CONCERT SOUND':'ARENA SOUND'},isMotionPaused:()=>paused,reducedMotion:()=>reduced.matches});
